  'plans.faqWhatIsPlus': 'Chatyy One काय आहे?',
  'plans.faqWhatIsPlusAnswer': 'हे Chatyy चे प्रीमियम प्लान आहे जे तुमच्या सर्व संवाद, फोटो आणि व्हिडिओंची सुरक्षा करते. Chatyy One सह, तुम्ही काहीतरी चुकून हटवले तरी, तुम्ही 30 दिवसांपर्यंत पुनर्प्राप्त करू शकता. याशिवाय, तुम्हाला 200GB स्टोरेज, One AI तुमच्या वैयक्तिक सहाय्यक म्हणून, आणि 100MB पर्यंत फाइल्स पाठवण्याची परवानगी मिळते.',
  'plans.faqCancelAnswer': 'तुमची योजना भरणा केलेल्या कालावधीच्या शेवटी सक्रिय राहील. त्यानंतर, तुम्ही मोफत योजनावर परत जाल. तुमच्या 15GB पेक्षा जास्त फोटो आणि व्हिडिओ 30 दिवसांपर्यंत डाउनलोडसाठी ठेवले जातील.',
  'plans.faqHowFamily': 'Pro योजना कशी कार्य करते?',
  'plans.faqHowFamilyAnswer': 'तुम्ही तुमच्या कुटुंबातील 4 लोकांना जोडू शकता. सर्वांनी 500GB स्टोरेज शेअर केले आहे आणि Chatyy One च्या सर्व फायद्यांचा लाभ घेतात. प्रत्येक व्यक्तीला त्यांचा खासगी जागा आहे — कोणीही दुसऱ्यांचे फाइल्स पाहत नाही.',
  'plans.faqChangePlanAnswer': 'होय! जर तुम्ही Plus वरून Pro मध्ये अपग्रेड केला, तर फक्त प्रमाणानुसार फरक आकारला जाईल. जर तुम्ही डाउनग्रेड केला, तर सध्याची योजना कालावधीच्या शेवटीपर्यंत चालू राहील.',
  'plans.faqCardDeclined': 'माझे कार्ड नाकारले गेले, मी काय करू?',
  'plans.faqCardDeclinedAnswer': 'तुमच्याकडे तुमचे कार्ड अपडेट करण्यासाठी 7 दिवस आहेत. या कालावधीत, तुमचे सर्व फायदे कार्यरत राहतील. 7 दिवसांनंतर, योजना मोफतवर परत जाईल.',
  'plans.faqDataSafe': 'माझे डेटा सुरक्षित आहेत का?',
  'plans.faqDataSafeAnswer': 'होय! तुमच्या पेमेंट डेटा एन्ड-टू-एन्ड एन्क्रिप्शनसह प्रक्रिया केली जाते. आम्ही तुमच्या कार्डाचा क्रमांक संग्रहित करत नाही — फक्त तुमच्या संदर्भासाठी शेवटचे 4 अंक.',
